(* [comment removed for export] *)
Record svce := mkSE { se_addr : Z ; se_hdr : svch ; se_tiname : Z }.

Definition svch_ok (S : svch) : Prop :=
  0 <= sv_vptr S < 2^64 /\ 0 <= sv_ti S < 2^64 /\ 0 <= sv_id S < 2^64 /\ 0 <= sv_owner S < 2^64
  /\ 0 <= sv_next S < 2^64 /\ 0 <= sv_destroy S < 2^64.

(* [comment removed for export] *)
Definition keys_match (kti kid kname : Z) (e : svce) : bool :=
  (negb (sv_id (se_hdr e) =? 0) && (sv_id (se_hdr e) =? kid))
  || (negb (sv_ti (se_hdr e) =? 0) && negb (kti =? 0) && (se_tiname e =? kname)).

(* [comment removed for export] *)
Fixpoint find_svc (kti kid kname : Z) (L : list svce) : Z :=
  match L with
  | [] => 0
  | e :: L' => if keys_match kti kid kname e then se_addr e else find_svc kti kid kname L'
  end.

(* [comment removed for export] *)
Ltac if_tk := let K := fresh "K" in if_cases K;
  [ clear K | exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] ].
Ltac if_nt := let K := fresh "K" in if_cases K;
  [ exfalso; zify_cond K; unfold wz in K; rewrite ?unsigned_lit in K by lia; first [lia | congruence] | clear K ].

(* [comment removed for export] *)
Ltac retlit :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
      replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [lia| reflexivity])
  | |- evt _ _ (MS _ _ (Z_to_bv 64 _) _ _ _ _) => idtac
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "retlit: unexpected pc" pc
  end.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Fixpoint SvcChain (m : mem) (first : Z) (L : list svce) : Prop :=
  match L with
  | [] => first = 0
  | e :: L' =>
      first = se_addr e /\ 0 < se_addr e /\ se_addr e + 48 <= 2^64
      /\ ro_cells usegs m (se_addr e) (SvcHdrCells (se_hdr e)) /\ svch_ok (se_hdr e)
      /\ (sv_ti (se_hdr e) <> 0 ->
            ro_cells usegs m (sv_ti (se_hdr e) + 8) [C8 (wz (se_tiname e))] /\ 0 <= se_tiname e < 2^64
            /\ 0x7e000 <= sv_ti (se_hdr e) + 8 /\ sv_ti (se_hdr e) + 16 <= 0x7f000)
      /\ SvcChain m (sv_next (se_hdr e)) L'
  end.

(* [comment removed for export] *)
Definition svce_off (W : list (Z * Z)) (e : svce) : Prop := disjoint_from W (se_addr e) 48.

Lemma disjoint_from_statics : forall W A n,
  Forall (fun iv : Z * Z => 0xb8000 <= fst iv \/ snd iv <= 0x10000) W ->
  0x10000 <= A -> A + n <= 0xb8000 -> disjoint_from W A n.
Proof.
  intros W A n FW LO HI. induction W as [|[lo hi] W IH]; [exact I|].
  pose proof (Forall_inv FW) as H1. cbn in H1. cbn. split; [lia|]. apply IH. exact (Forall_inv_tail FW).
Qed.

Lemma SvcChain_transport : forall W m m' first L,
  SvcChain m first L -> munch W m m' ->
  Forall (fun iv : Z * Z => 0xb8000 <= fst iv \/ snd iv <= 0x10000) W ->
  Forall (svce_off W) L -> SvcChain m' first L.
Proof.
  intros W m m' first L. revert first. induction L as [|e L IH]; intros first CH MU FW OFF; [exact CH|].
  cbn in CH |- *. destruct CH as (E & POS & HI & HD & OK & TI & CH').
  pose proof (Forall_inv OFF) as O1. unfold svce_off in O1.
  split; [exact E|]. split; [exact POS|]. split; [exact HI|].
  split. { eapply ro_cells_transport; [exact HD| exact MU|]. cbn [cells_size csize Nat.add SvcHdrCells]. exact O1. }
  split; [exact OK|]. split.
  { intros NZ. destruct (TI NZ) as (RO & R & LO' & HI'). split; [| split; [exact R| split; [exact LO'| exact HI']]].
    eapply ro_cells_transport; [exact RO| exact MU|]. cbn [cells_size csize Nat.add]. apply disjoint_from_statics; [exact FW| lia| lia]. }
  apply IH; [exact CH'| exact MU| exact FW| exact (Forall_inv_tail OFF)].
Qed.

Lemma SvcChain_nil_inv : forall m first, SvcChain m first [] -> first = 0.
Proof. intros m first H. exact H. Qed.

Lemma SvcChain_head : forall m first L, SvcChain m first L -> L <> [] -> 0 < first /\ first + 48 <= 2^64.
Proof. intros m first [|e L] CH NE; [congruence|]. cbn in CH. destruct CH as (-> & POS & HI & _). lia. Qed.

Lemma SvcChain_zero : forall m L, SvcChain m 0 L -> L = [].
Proof. intros m [|e L] CH; [reflexivity|]. cbn in CH. destruct CH as (E & POS & _). lia. Qed.

(* [comment removed for export] *)
Lemma keys_match_false_inv : forall kti kid kname e,
  keys_match kti kid kname e = false ->
  (sv_id (se_hdr e) = 0 \/ sv_id (se_hdr e) <> kid)
  /\ (sv_ti (se_hdr e) = 0 \/ kti = 0 \/ se_tiname e <> kname).
Proof.
  intros kti kid kname e H. unfold keys_match in H.
  apply orb_false_iff in H. destruct H as [H1 H2].
  apply andb_false_iff in H1. apply andb_false_iff in H2.
  split.
  - destruct H1 as [H1|H1].
    + left. apply negb_false_iff in H1. apply Z.eqb_eq in H1. exact H1.
    + right. apply Z.eqb_neq in H1. exact H1.
  - destruct H2 as [H2|H2].
    + apply andb_false_iff in H2. destruct H2 as [H2|H2]; apply negb_false_iff in H2; apply Z.eqb_eq in H2; lia.
    + right; right. apply Z.eqb_neq in H2. exact H2.
Qed.

(* [comment removed for export] *)
Definition svce_al (e : svce) : Prop := se_addr e mod 8 = 0 /\ (sv_ti (se_hdr e) <> 0 -> sv_ti (se_hdr e) mod 8 = 0).

