Definition P_UB_SLOCK_DTOR   : Z := 0x2d758.
Definition P_UB_SLOCK_UNLOCK : Z := 0x325cc.
Definition P_UB_SLOCK_LOCK   : Z := 0x3261c.
Definition SLOCK_DTOR_STACK : Z := 16 + MUTEX_UNLOCK_STACK.
Definition SLOCK_LOCK_STACK : Z := 16.

Definition slock_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (M lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 a4 a5 a6 a7 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (M, M + 40)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ PMutex m' M 0.

(* [comment removed for export] *)
Definition slock_dtor_stmt : Prop :=
  forall (SL M lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ro_cells usegs m SL [C8 (wz M)] -> ro_cells usegs m (SL + 8) [C1 (b8 1)] -> PMutex m M EBUSY ->
  (SL + 16 <= lo \/ bv_unsigned sp <= SL) -> (M + 40 <= lo \/ bv_unsigned sp <= M) -> 0 < M -> M mod 8 = 0 ->
  stk usegs m lo (bv_unsigned sp) -> lo + SLOCK_DTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (slock_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc M lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz SL) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_SLOCK_DTOR) fc None m (seg_rom usegs)).
