(* [comment removed for export] *)
Lemma dus_loop2 : forall L (cur kti kid kname : Z)
    ra sp gp tp t0 t1 t2 s0 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  SvcChain m cur L -> L <> [] ->
  Forall (fun e => keys_match kti kid kname e = false) L -> Forall svce_al L ->
  (kti <> 0 -> ro_cells usegs m (kti + 8) [C8 (wz kname)]) ->
  0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 -> kti mod 8 = 0 ->
  mem_inv usegs m ->
  evt usegs (fun ms' => exists a3' a4',
               ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (wz 0) (wz kti) (wz kid) (wz 0) a3' a4' a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 P_DUS_SCAN2_NONE) fc None m (seg_rom usegs))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (wz cur) (wz kti) (wz kid) (wz 0) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
