Lemma XS_tiname_config : forall m, XStatics m -> ro_cells usegs m (L_TYPEID_CONFIG + 8) [C8 (wz TI_NAME_CONFIG)].
Proof.
  intros m XS. destruct XS as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & H0 & _).
  destruct H0 as [H0 _]. exact H0.
Qed.
