Definition msc_segA_post (sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (r hintp ioc allocb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a3 m' j3 j1,
    ms' = MS (mkR (Z_to_bv 64 P_MSC_RET1) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 ioc) (Z_to_bv 64 hintp) (Z_to_bv 64 allocb) (Z_to_bv 64 56) (Z_to_bv 64 8) a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOCIMPL_ALLOCATE) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -80)
    /\ rw_cells usegs m' (bv_unsigned sp + -80)
         [CB 8 j3; C8 s1; C8 (Z_to_bv 64 r); C8 (Z_to_bv 64 (P_UB_CREATE_CONFIG + 36));
          C8 (Z_to_bv 64 allocb); C8 (Z_to_bv 64 (P_MAKE_SVC_CONFIG + 48));
          CB 8 j1; C8 s1; C8 s0; C8 ra].

Lemma msc_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (r hintp ioc allocb owner first lo : Z) (jal : list byte),
  ro_cells usegs m (r + O_REG_OWNER) [C8 (wz ioc)] -> ro_cells usegs m ioc [C8 (wz allocb)] ->
  rw_cells usegs m allocb [C8 (wz VP_ALLOCIMPL); CB 8 jal] -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> hceil <= lo ->
  r + NEWSZ_REG <= lo -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 -> allocb + SZ_ALLOCIMPL <= lo ->
  0 <= hintp < 2^64 ->
  ioc mod 8 = 0 -> 0 < allocb -> allocb mod 8 = 0 ->                                          (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (msc_segA_post sp gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc r hintp ioc allocb lo ra s0 s1 m)
