(* [comment removed for export] *)
Definition dusc_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (r v ctx first kti kid lo : Z) (S1 : svch) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (das_W lo sp r v) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ Registry LB m' r ctx v 0
    /\ rw_cells usegs m' v (SvcHdrCells (mkSVC (sv_vptr S1) kti kid (sv_owner S1) first (sv_destroy S1))).

Lemma dusc_segB : forall (r K v lo : Z) (LB : list block) (L : list svce) (S1 : svch) (ctx first kti kid kname : Z)
    sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra s0 s1 s2 s3 s4 s1x s3x s4x : word)
    (F : bvmap 5 word) fc (m : mem) (j0 j7 : list byte),
  rw_cells usegs m (bv_unsigned sp + -80) [CB 16 j0; C8 (Z_to_bv 64 (r + 8))] ->
  rw_cells usegs m (bv_unsigned sp + -56) [C1 (b8 0)] ->
  rw_cells usegs m (bv_unsigned sp + -55) [CB 7 j7; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells usegs m v (SvcHdrCells S1) -> svch_ok S1 ->
  Registry LB m r ctx first 0 ->
  ro_cells usegs m K [C8 (wz kti); C8 (wz kid)] -> 0 <= kti < 2^64 -> 0 <= kid < 2^64 -> 0 <= kname < 2^64 ->
  (kti <> 0 -> ro_cells usegs m (kti + 8) [C8 (wz kname)] /\ 0x10000 <= kti + 8 /\ kti + 16 <= 0xb8000) ->
  SvcChain m first L -> Forall (fun e => keys_match kti kid kname e = false) L ->
  Forall (svce_off (das_W lo sp r v)) L ->
  bv_unsigned sp <= K -> K + 16 <= 2^64 ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb8000 <= r) ->
  v + SZ_SVC <= lo -> (v + SZ_SVC <= 0x10000 \/ 0xb8000 <= v) ->
  (r + NEWSZ_REG <= v \/ v + SZ_SVC <= r) ->
  stk usegs m lo (bv_unsigned sp + -80) -> lo + DUS_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  kti mod 8 = 0 -> Forall svce_al L -> r mod 8 = 0 -> 0 < v -> v mod 8 = 0 ->                       (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (dusc_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB r v ctx first kti kid lo S1 m)
    (MS (mkR (Z_to_bv 64 P_DUSC_RET) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
             (Z_to_bv 64 r) s1x (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 K) s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DUSC_RET) fc None m (seg_rom usegs)).
