  Definition make_svc_config_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (r ioc allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (A : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range A NEWSZ_CFG /\ hs_RHEAP H s' ((p, A, NEWSZ_CFG) :: LB) m'
      /\ ConfigSvc ((p, A, NEWSZ_CFG) :: LB) m' A (cfg_hdr ioc)
      /\ Registry ((p, A, NEWSZ_CFG) :: LB) m' r ioc A 0
      /\ AllocImpl ((p, A, NEWSZ_CFG) :: LB) m' allocb
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(r, r + NEWSZ_REG)] m m'.

  Definition make_svc_config_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (r hintp ioc allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 r -> a1 = Z_to_bv 64 hintp ->
      Registry LB m r ioc 0 0 ->
      ro_cells usegs m ioc [C8 (wz allocb)] -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 ->
      ioc mod 8 = 0 ->                                                                  (* [comment removed for export] *)
      AllocImpl LB m allocb ->
      ro_cells usegs m hintp [C4 (wz 4294967295)] -> bv_unsigned sp <= hintp -> hintp + 4 <= 2^64 ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_CFG <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - MAKE_SVC_CONFIG_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (make_svc_config_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB r ioc allocb lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_MAKE_SVC_CONFIG) fc None m (seg_rom usegs)) mo).

  Lemma make_svc_config_spec : make_svc_config_stmt.
  Proof.
